const question = (prompt, correct, wrong, other, explanation, wrongFeedback, otherFeedback) => ({
  prompt, explanation, correct: 'reasoned',
  options: [
    { id: 'reasoned', label: correct, feedback: explanation },
    { id: 'trap', label: wrong, feedback: wrongFeedback },
    { id: 'alternative', label: other, feedback: otherFeedback },
  ],
})
const drill = (id, title, first, second) => ({ id, title, variants: [first, second] })
const source = pages => ({ document: 'Consult Club IIMA Casebook (2020–21)', pages })
const source2026 = pages => ({ document: 'Consult Club IIMA Prep Book (2026–27)', pages })
const hbs = pages => ({ document: 'HBS MCC Case Interview Guide', pages })
const fmt = value => value.toLocaleString('en-US', { maximumFractionDigits: 2 })
const dollars = value => `${value < 0 ? '−' : ''}$${fmt(Math.abs(value))}`

export function seededRandom(seed) {
  let value = seed >>> 0
  return () => {
    value += 0x6D2B79F5
    let next = Math.imul(value ^ value >>> 15, value | 1)
    next ^= next + Math.imul(next ^ next >>> 7, next | 61)
    return ((next ^ next >>> 14) >>> 0) / 4294967296
  }
}

function quantitative(kind, context, seed) {
  const random = seededRandom(seed)
  const pick = values => values[Math.floor(random() * values.length)]
  let inputs, expected, labels, prompt, working, mistakes
  if (kind === 'margin') {
    const revenue = pick([800, 1000, 1200]), margin = pick([10, 15, 20]), growth = pick([25, 50, 100])
    const profit = revenue * margin / 100, nextRevenue = revenue * (1 + growth / 100)
    inputs = { revenue, profit, nextRevenue }; expected = profit / nextRevenue * 100
    prompt = `${context} Revenue rises from ${dollars(revenue)}k to ${dollars(nextRevenue)}k while operating profit stays at ${dollars(profit)}k. What is the new operating margin?`
    labels = [expected, margin, margin * (1 + growth / 100)].map(value => `${fmt(value)}%`)
    working = `Margin = profit ÷ revenue. ${fmt(profit)} ÷ ${fmt(nextRevenue)} × 100 = ${fmt(expected)}%. More revenue does not guarantee a better margin.`
    mistakes = ['This is the original margin. The revenue denominator has changed.', 'This increases margin with revenue even though profit is unchanged; the ratio should fall.']
  } else if (kind === 'break-even') {
    const units = pick([500, 800, 1200]), contribution = pick([25, 40, 60]), price = contribution * 3, variableCost = contribution * 2, fixedCost = units * contribution
    inputs = { fixedCost, price, variableCost }; expected = units
    prompt = `${context} Fixed cost is ${dollars(fixedCost)}, price is ${dollars(price)} per unit, and variable cost is ${dollars(variableCost)} per unit. How many units are needed to break even?`
    labels = [expected, Math.ceil(fixedCost / price), Math.ceil(fixedCost / variableCost)].map(value => `${fmt(value)} units`)
    working = `Contribution per unit = ${price} − ${variableCost} = ${contribution}. Break-even units = ${fmt(fixedCost)} ÷ ${contribution} = ${fmt(expected)}.`
    mistakes = ['Dividing by price ignores the variable cost of delivering each unit.', 'Variable cost is not the contribution available to recover fixed cost.']
  } else if (kind === 'capacity') {
    const base = pick([30, 40, 60]), rates = [base + 10, base - 5, base]
    inputs = { rates }; expected = Math.min(...rates)
    prompt = `${context} Three sequential stages can process ${rates.join(', ')} units per hour. With sufficient demand and no other losses, what is the maximum sustainable line throughput?`
    labels = [expected, Math.max(...rates), rates.reduce((a, b) => a + b, 0)].map(value => `${value} units/hour`)
    working = `The slowest stage limits a sequential process: min(${rates.join(', ')}) = ${expected} units/hour. Speeding up a non-bottleneck does not raise this ceiling.`
    mistakes = ['The fastest stage cannot overcome the slower stage downstream or upstream.', 'These are sequential stages, not independent parallel production lines; their capacities cannot be added.']
  } else if (kind === 'growth') {
    const marketGrowth = pick([5, 10, 20]), relativeShareGrowth = pick([10, 20, 25])
    inputs = { marketGrowth, relativeShareGrowth }; expected = ((1 + marketGrowth / 100) * (1 + relativeShareGrowth / 100) - 1) * 100
    prompt = `${context} The market grows ${marketGrowth}%, and the company’s market share increases by ${relativeShareGrowth}% relative to its previous share. With prices unchanged, what is revenue growth?`
    labels = [expected, marketGrowth + relativeShareGrowth, marketGrowth].map(value => `${fmt(value)}%`)
    working = `Multiply the drivers: (1 + ${marketGrowth / 100}) × (1 + ${relativeShareGrowth / 100}) − 1 = ${fmt(expected)}%. The share change is relative, not percentage points.`
    mistakes = ['Adding the growth rates misses the interaction term.', 'This includes market growth but ignores the increase in the company’s share.']
  } else if (kind === 'entry-profit') {
    const marketUnits = pick([10000, 20000, 30000]), share = pick([5, 10]), price = pick([80, 100]), variableCost = price - pick([20, 40]), fixedCost = pick([10000, 15000])
    inputs = { marketUnits, share, price, variableCost, fixedCost }; expected = marketUnits * share / 100 * (price - variableCost) - fixedCost
    prompt = `${context} Annual market size is ${fmt(marketUnits)} units; attainable share is ${share}%. Price is ${dollars(price)}, variable cost ${dollars(variableCost)} per unit, and annual fixed cost ${dollars(fixedCost)}. What is annual operating profit?`
    labels = [expected, marketUnits * share / 100 * price, marketUnits * (price - variableCost) - fixedCost].map(dollars)
    working = `Expected volume = ${fmt(marketUnits)} × ${share}% = ${fmt(marketUnits * share / 100)}. Profit = volume × (${price} − ${variableCost}) − ${fmt(fixedCost)} = ${dollars(expected)}.`
    mistakes = ['This is revenue at the attainable share, not profit after variable and fixed costs.', 'This assumes the company wins the entire market instead of the stated attainable share.']
  } else if (kind === 'value-payback') {
    const replacement = pick([200, 300, 400]), labour = replacement / 2, replacements = pick([2, 3]), price = replacement * pick([9, 12, 15])
    inputs = { replacement, labour, replacements, price }; expected = price / ((replacement + labour) * replacements)
    prompt = `${context} A replacement costs ${dollars(replacement)} in parts and ${dollars(labour)} in labour, ${replacements} times a year. A new product costing ${dollars(price)} avoids these costs. What is simple payback, ignoring discounting and other costs?`
    labels = [expected, price / (replacement * replacements), price / (replacement + labour)].map(value => `${fmt(value)} years`)
    working = `Annual avoided cost = (${replacement} + ${labour}) × ${replacements} = ${fmt((replacement + labour) * replacements)}. Payback = ${fmt(price)} ÷ annual avoided cost = ${fmt(expected)} years. This is not proof of willingness to pay.`
    mistakes = ['This omits labour from the avoided replacement cost.', 'This uses the cost of one replacement rather than the annual cost.']
  } else if (kind === 'roce') {
    const profit = pick([200, 300, 400]), capital = profit * pick([4, 5, 8]), nextCapital = capital * pick([1.25, 1.5])
    inputs = { profit, capital, nextCapital }; expected = profit / nextCapital * 100
    prompt = `${context} Annual operating profit stays at ${dollars(profit)}k while capital employed rises from ${dollars(capital)}k to ${dollars(nextCapital)}k. Using the stated capital balance, what is the new return on capital employed?`
    labels = [expected, profit / capital * 100, profit / (nextCapital - capital) * 100].map(value => `${fmt(value)}%`)
    working = `ROCE = operating profit ÷ capital employed. ${profit} ÷ ${fmt(nextCapital)} × 100 = ${fmt(expected)}%. Inspect working capital as well as fixed assets when the denominator grows.`
    mistakes = ['This uses the old capital balance rather than the new denominator.', 'This divides total operating profit by only the increase in capital, not total capital employed.']
  } else {
    const total = pick([10000, 20000, 30000]), share = pick([10, 20, 25]), subtotal = total * (1 - share / 100)
    inputs = { subtotal, share }; expected = total
    prompt = `${context} Revenue before advertising is ${dollars(subtotal)}. Advertising is ${share}% of TOTAL revenue. What is total revenue?`
    labels = [expected, subtotal * (1 + share / 100), subtotal].map(dollars)
    working = `Non-ad revenue is ${100 - share}% of total. Total = ${fmt(subtotal)} ÷ ${1 - share / 100} = ${dollars(expected)}. A percentage of total is not a markup on the subtotal.`
    mistakes = ['This adds a percentage of the subtotal, but the question defines the share using total revenue.', 'This leaves out advertising altogether.']
  }
  return { ...question(prompt, ...labels, working, ...mistakes), calculation: true, math: { kind, inputs, expected }, dataNote: 'Illustrative practice figures; use only the assumptions stated here.' }
}
const numberDrill = (id, title, kind, first, second) => drill(id, title, seed => quantitative(kind, first, seed), seed => quantitative(kind, second, seed))

