export const FRAMEWORK_DRILLS = FRAMEWORKS.flatMap(framework => framework.drills.map(drill => ({ ...drill, id: `${framework.id}/${drill.id}`, frameworkId: framework.id })))

export function makeFrameworkQuestion(drillId, variant, seed) {
  const item = FRAMEWORK_DRILLS.find(drill => drill.id === drillId)
  if (!item || !Number.isInteger(variant) || variant < 0 || variant >= item.variants.length) throw new Error('Unknown framework drill')
  const template = item.variants[variant]
  return typeof template === 'function' ? template(seed) : template
}
